-- =====================================================================
--  ARCHIVO 03: CARGA DE DATOS (generado por generador/generar_datos.py)
--  PRODUCT 100 | SUPPLY_ORDER 1000 | ORDER_DETAIL 1500 | BATCH 500 | BATCH_DETAIL 500
--
--  REQUISITO: CATEGORY, SUPPLIER y EMPLOYEE ya deben tener datos (los llena
--  el equipo). Este script NO usa IDs fijos de esas tablas: los toma de lo
--  que exista, repartiéndolos en orden (por eso sirve con cualquier dato).
--  Para que las categorías tengan sentido, cree las categorías en el orden de
--  03a_datos_base_ejemplo.sql (si hay menos de 20, se reparten en ciclo).
--
--  Todo va en una transacción y con los triggers ACTIVOS.
-- =====================================================================
SET search_path TO inventario_postobon;
BEGIN;

-- Validación previa: si falta alguna tabla base, se detiene con un mensaje claro
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM category) THEN RAISE EXCEPTION 'Primero llene CATEGORY'; END IF;
    IF NOT EXISTS (SELECT 1 FROM supplier) THEN RAISE EXCEPTION 'Primero llene SUPPLIER'; END IF;
    IF NOT EXISTS (SELECT 1 FROM employee) THEN RAISE EXCEPTION 'Primero llene EMPLOYEE'; END IF;
END $$;

-- Tablas puente temporales: posición (1, 2, 3...) -> ID real
CREATE TEMP TABLE map_category ON COMMIT DROP AS
  SELECT row_number() OVER (ORDER BY category_id) AS pos, category_id AS id FROM category;
CREATE TEMP TABLE map_supplier ON COMMIT DROP AS
  SELECT row_number() OVER (ORDER BY supplier_id) AS pos, supplier_id AS id FROM supplier;
CREATE TEMP TABLE map_employee ON COMMIT DROP AS
  SELECT row_number() OVER (ORDER BY employee_id) AS pos, employee_id AS id FROM employee;

